### Solution:
```csharp
using System;
using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;
using Microsoft.EntityFrameworkCore;

namespace SocialMediaPlatform.Models
{
    public class User
    {
        public int UserId { get; set; }

        [Required]
        [MaxLength(50)]
        public string Username { get; set; }

        [MaxLength(200)]
        public string Bio { get; set; }

        public List<Post> Posts { get; set; }
        public List<Comment> Comments { get; set; }
    }

    public class Post
    {
        public int PostId { get; set; }

        [Required]
        public string Content { get; set; }

        public List<Hashtag> Hashtags { get; set; }

        public int UserId { get; set; }
        public User User { get; set; }

        public List<Comment> Comments { get; set; }
    }

    public class Comment
    {
        public int CommentId { get; set; }

        [Required]
        public string Content { get; set; }

        public int UserId { get; set; }
        public User User { get; set; }

        public int PostId { get; set; }
        public Post Post { get; set; }
    }

    public class Hashtag
    {
        public int HashtagId { get; set; }

        [Required]
        [MaxLength(50)]
        public string Name { get; set; }

        public List<Post> Posts { get; set; }
    }

    public class SocialMediaContext : DbContext
    {
        public DbSet<User> Users { get; set; }
        public DbSet<Post> Posts { get; set; }
        public DbSet<Comment> Comments { get; set; }
        public DbSet<Hashtag> Hashtags { get; set; }

        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            modelBuilder.Entity<User>()
                .HasMany(u => u.Posts)
                .WithOne(p => p.User)
                .HasForeignKey(p => p.UserId);

            modelBuilder.Entity<User>()
                .HasMany(u => u.Comments)
                .WithOne(c => c.User)
                .HasForeignKey(c => c.UserId);

            modelBuilder.Entity<Post>()
                .HasMany(p => p.Comments)
                .WithOne(c => c.Post)
                .HasForeignKey(c => c.PostId);

            modelBuilder.Entity<Post>()
                .HasMany(p => p.Hashtags)
                .WithMany(h => h.Posts)
                .UsingEntity(j => j.ToTable("PostHashtags"));

            modelBuilder.Entity<Hashtag>()
                .HasMany(h => h.Posts)
                .WithMany(p => p.Hashtags)
                .UsingEntity(j => j.ToTable("PostHashtags"));
        }
    }
}
```

In this solution, the `User`, `Post`, `Comment`, and `Hashtag` classes represent the entities in the social media platform. The `SocialMediaContext` class defines the relationships between these entities using the fluent API configurations. The relationships include one-to-many relationships between users and posts/comments, many-to-many relationships between posts and hashtags, and the necessary foreign key constraints. This schema allows for the representation of user profiles, posts, and comments with appropriate associations and constraints.

