        String pattern3 = "(ghi";
        System.out.println("Modified pattern: " + manipulatePattern(pattern3)); // Output: Modified pattern = "(ghi)"

        String pattern4 = "jkl)";
        System.out.println("Modified pattern: " + manipulatePattern(pattern4)); // Output: Modified pattern = "(jkl)"
    }
}
