You are tasked with implementing a hash table data structure in C++ using separate chaining for collision resolution. The hash table should support key-value pairs, and the keys will be of type `int` and the values will be of type `string`. You need to implement the following functionalities for the hash table:
1. Insert a key-value pair into the hash table.
2. Remove a key-value pair from the hash table.
3. Retrieve the value associated with a given key from the hash table.
4. Check if a key exists in the hash table.

You are provided with a header file `hash.hh` that contains the following class definition for the hash table:

```cpp
#ifndef HASH_HH
#define HASH_HH

#include <string>

class HashTable {
public:
    HashTable(int size);  // Constructor to initialize the hash table with a given size
    void insert(int key, const std::string& value);  // Insert a key-value pair into the hash table
    void remove(int key);  // Remove a key-value pair from the hash table
    std::string retrieve(int key);  // Retrieve the value associated with a given key
    bool exists(int key);  // Check if a key exists in the hash table
};

#endif
```

You need to implement the member functions of the `HashTable` class in a separate source file `hash.cpp`. The hash function for the keys is provided as follows:

```cpp
int hashFunction(int key, int tableSize) {
    return key % tableSize;
}
```

Your task is to complete the implementation of the `HashTable` class in `hash.cpp` using separate chaining for collision resolution and ensure that all the functionalities work correctly.

### Solution:
```cpp
#include "hash.hh"
#include <vector>
#include <list>

class HashTable {
private:
    int size;
    std::vector<std::list<std::pair<int, std::string>>> table;

public:
    HashTable(int size) : size(size), table(size) {}

    void insert(int key, const std::string& value) {
        int index = hashFunction(key, size);
        for (const auto& pair : table[index]) {
            if (pair.first == key) {
                // Key already exists, update the value
                pair.second = value;
                return;
            }
        }
        table[index].push_back(std::make_pair(key, value));
    }

    void remove(int key) {
        int index = hashFunction(key, size);
        table[index].remove_if([key](const std::pair<int, std::string>& pair) {
            return pair.first == key;
        });
    }

    std::string retrieve(int key) {
        int index = hashFunction(key, size);
        for (const auto& pair : table[index]) {
            if (pair.first == key) {
                return pair.second;
            }
        }
        return "";  // Key not found
    }

    bool exists(int key) {
        int index = hashFunction(key, size);
        for (const auto& pair : table[index]) {
            if (pair.first == key) {
                return true;
            }
        }
        return false;
    }
};
```

