function generateTagCloud($tags) {
    $tagCounts = array_count_values($tags); // Count the frequency of each tag
    arsort($tagCounts); // Sort the tags based on frequency in descending order

    $html = '<div class="tag-cloud">';
    $tagSize = 1;
    foreach ($tagCounts as $tag => $count) {
        $html .= '<a href="tag_link_' . urlencode($tag) . '" class="tag-size-' . $tagSize . '">' . htmlspecialchars($tag) . '</a>';
