class String {
private:
    char* original;

public:
    // Constructor from C-style string
    String(const char* str) {
        original = new char[strlen(str) + 1];
        strcpy(original, str);
    }

    // Copy constructor
    String(const String& other) {
        original = new char[strlen(other.original) + 1];
        strcpy(original, other.original);
    }

    // Assignment operator
    String& operator=(const String& target) {
        if (this != &target) {
            delete[] original;
            original = new char[strlen(target.original) + 1];
            strcpy(original, target.original);
        }
        return *this;
    }

    // Concatenation operator
    String operator+(const String& other) const {
        char* newStr = new char[strlen(original) + strlen(other.original) + 1];
        strcpy(newStr, original);
        strcat(newStr, other.original);
        String result(newStr);
        delete[] newStr;
        return result;
    }

    // Comparison operators
    bool operator==(const String& other) const {
        return strcmp(original, other.original) == 0;
    }

    bool operator!=(const String& other) const {
        return strcmp(original, other.original) != 0;
    }

    // Indexing operator
    char& operator[](size_t index) {
        return original[index];
    }

    // Destructor
    ~String() {
        delete[] original;
    }
};

int main() {
    String s1("Hello");
    String s2("World");
    String s3 = s1 + s2;
    std::cout << "s3: " << s3 << std::endl;
    std::cout << "s1 == s2: " << (s1 == s2) << std::endl;
    std::cout << "s1 != s2: " << (s1 != s2) << std::endl;
    std::cout << "s3[0]: " << s3[0] << std::endl;
    return 0;
}
```

### Problem:
You are tasked with implementing a custom `char_traits` class in C++. The `char_traits` class template provides a set of operations for manipulating and comparing characters. Your task is to create a custom `char_traits` class that supports the following operations:
1. Comparison of characters
2. Copying characters
3. Assigning characters
4. Finding characters within a given range

You should implement the following member functions for the custom `char_traits` class:
1. `static int compare(const char_type* s1, const char_type* s2, size_t n)`: This function compares the first `n` characters of the character arrays `s1` and `s2`. It should return a negative value if `s1` is less than `s2`, zero if they are equal, or a positive value if `s1` is greater than `s2`.
2. `static char_type* copy(char_type* dest, const char_type* src, size_t n)`: This function copies `n` characters from the character array `src` to the character array `dest` and returns a pointer to the destination array.
3. `static char_type* assign(char_type* dest, size_t n, char_type a)`: This function assigns the character `a` to the first `n` characters of the character array `dest` and returns a pointer to the destination array.
4. `static const char_type* find(const char_type* s, size_t n, const char_type& a)`: This function searches for the first occurrence of the character `a` within the first `n` characters of the character array `s` and returns a pointer to the located character or a null pointer if `a` is not found.

Your task is to implement the custom `char_traits` class with the specified member functions and demonstrate its usage in a simple program.

### Solution:
```cpp
#include <iostream>

template <typename CharT>
struct custom_char_traits : public std::char_traits<CharT> {
    using char_type = CharT;

    static int compare(const char_type* s1, const char_type* s2, size_t n) {
        for (size_t i = 0; i < n; ++i) {
            if (s1[i] < s2[i]) return -1;
            if (s1[i] > s2[i]) return 1;
        }
        return 0;
    }

    static char_type* copy(char_type* dest, const char_type* src, size_t n) {
        for (size_t i = 0; i < n; ++i) {
            dest[i] = src[i];
        }
        return dest;
    }

    static char_type* assign(char_type* dest, size_t n, char_type a) {
        for (size_t i = 0; i < n; ++i) {
            dest[i] = a;
        }
        return dest;
    }

    static const char_type* find(const char_type* s, size_t n, const char_type& a) {
        for (size_t i = 0; i < n; ++i) {
            if (s[i] == a) return &s[i];
        }
        return nullptr;
    }
};

int main() {
    using traits = custom_char_traits<char>;
    char str1[] = "Hello";
    char str2[] = "World";

    std::cout << "Comparison: " << traits::compare(str1, str2, 3) << std::endl;

    char dest[6];
    traits::copy(dest, str1, 5);
    std::cout << "Copy: " << dest << std::endl;

    char assign_dest[6];
    traits::assign(assign_dest, 5, 'A');
    std::cout << "Assign: " << assign_dest << std::endl;

    const char* found = traits::find(str1, 5, 'l');
    if (found != nullptr) {
        std::cout << "Found: " << *found << std::endl;
    } else {
        std::cout << "Not found" << std::endl;
    }

    return 0;
}
```

### Problem:
You are tasked with implementing a function to convert a given decimal number to its hexadecimal representation. The hexadecimal representation should be in lowercase and should not contain any leading zeros. You should use the provided `kHexConversion` array to perform the conversion.

You are given the following code snippet as a reference:

```cpp
const char HashId::kHexConversion[] = "0123456789abcdef";
```

Implement the following function:

```cpp
std::string DecimalToHex(int decimal);
```

The function should take an integer `decimal` as input and return its hexadecimal representation as a string.

For example, if the input `decimal` is 305, the function should return "131" as 305 in hexadecimal is 0x131.

### Solution:
```cpp
#include <string>

class HashId {
public:
    static const char kHexConversion[];
};

const char HashId::kHexConversion[] = "0123456789abcdef";

std::string DecimalToHex(int decimal) {
    if (decimal == 0) {
        return "0";
    }

    std::string hex;
    while (decimal > 0) {
        int remainder = decimal % 16;
        hex = HashId::kHexConversion[remainder] + hex;
        decimal /= 16;
    }

    return hex;
}
```

The `DecimalToHex` function first handles the special case when the input `decimal` is 0. Then, it iteratively calculates the remainder when dividing the decimal number by 16 and appends the corresponding hexadecimal digit to the `hex` string. Finally, it returns the hexadecimal representation of the input decimal number.

