class BaseModelSchema:
    def __init__(self):
        self.fields = {}

    def add_field(self, name, field_type):
        self.fields[name] = field_type

    def generate_schema(self):
        schema = {}
        for field, field_type in self.fields.items():
            schema[field] = field_type.__name__
        return schema


