public class ChecksumValidator {
    public static boolean validateChecksum(byte[] data, int length, int checksum_low_byte) {
        int sum = 0;
        for (int i = 0; i < length; i++) {
            sum += data[i] & 0xFF; // Ensure the byte is treated as unsigned
        }
        return (sum & 0xFF) == checksum_low_byte;
    }
}
```

