public class VectorManipulation {
    public static void main(String[] args) {
        double[] vec = {1.0, 2.0, 3.0};
        double[] vecEntity = {2.0, 1.0, 3.0};
        double distOrg = 2.0;

        double[] vecMoved = calculateMovedVector(vec, vecEntity, distOrg);
        System.out.println("vecMoved = (" + vecMoved[0] + ", " + vecMoved[1] + ", " + vecMoved[2] + ")");
