    const char* server_port = "18811";
    tcp_client client(server_address, server_port);

    int a = -12;
    int b = 13;
    std::string operation = "add";
    std::string request = operation + " " + std::to_string(a) + " " + std::to_string(b);
    std::string response = client.send_request(request);

    int expected_result = a + b;
    int actual_result = std::stoi(response);

    if (actual_result == expected_result) {
        std::cout << "Result: " << actual_result << " (Expected: " << expected_result << ")" << std::endl;
