    buffer.AddIndex(10);
    buffer.AddIndex(20);
    buffer.AddIndex(30);

    std::cout << "Indices: ";
    for (int i = 0; i < buffer.GetSize(); ++i) {
        std::cout << buffer.GetIndex(i) << " ";
    }
    std::cout << std::endl;

    buffer.Resize(5);
    std::cout << "Resized Indices: ";
    for (int i = 0; i < buffer.GetSize(); ++i) {
        std::cout << buffer.GetIndex(i) << " ";
    }
    std::cout << std::endl;

    return 0;
}
