class DatabaseSession:
    def __enter__(self):
        # Enter the database session
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        # Exit the database session
        if exc_type is not None:
            self.rollback()
        self.remove()

    def add(self, status):
        # Add the status to the database
        self.db.add(status)

    def commit(self):
