```

Complete the implementation of the `transformer` meta-function within the `metal::detail` namespace to achieve the desired functionality.

### Solution:
```cpp
namespace metal {
    /// \cond
    namespace detail {
        template<class num, class... seqs>
        struct transformer_impl {
            template<template<class...> class expr>
            using type = expr<at<seqs, num>...>;
        };

        template<template<class...> class expr, class... seqs>
        struct transformer {
