public class AccruedAmountCalculator {
    public static double calculateAccruedAmount(double principal, double monthlyInterestRate, int periods) {
        double totalAmount = principal * Math.pow(1 + monthlyInterestRate, periods);
        return Math.round(totalAmount * 100.0) / 100.0; // rounding to two decimal places
    }

