class MissingContextVariable(KeyError):
    pass

class RequiredVariables:
    def __init__(self, *variables):
        self.variables = variables

    def __enter__(self):
        self.missing_variables = [var for var in self.variables if var not in locals()]
        if self.missing_variables:
            raise MissingContextVariable(f"Missing variables: {', '.join(self.missing_variables)}")

    def __exit__(self, exc_type, exc_value, traceback):
        pass

