		this.#parser = parser;
		this.#sourceCode = sourceCode;
		this.#ruleset = ruleset;
		this.#i18n = i18n;
		this.#ast = this.#parser.parse(this.#sourceCode);
		this.#document = new Document(this.#ast, this.#ruleset);
