import android.content.Context;
import android.text.format.DateFormat;

public abstract class TimePrintHelper {
    public static String getTime(Context context, int hour, int minute){
        if(DateFormat.is24HourFormat(context)){
            return ((hour<10)?"0"+hour:""+hour)+" : "+((minute<10)?"0"+minute:""+minute);
        } else {
            int formattedHour = (hour == 0 || hour == 12) ? 12 : hour % 12;
            String amPm = (hour < 12) ? "AM" : "PM";
            return ((formattedHour < 10) ? "0" + formattedHour : "" + formattedHour) + " : " + ((minute < 10) ? "0" + minute : "" + minute) + " " + amPm;
        }
    }
}
