### Solution:
```java
import java.util.ArrayList;
import java.util.List;

public abstract class TransList<U, T> {
    private List<T> list;

    public TransList(List<T> list) {
        this.list = list;
    }

    public abstract U trans(T v);

    public List<U> transform() {
        List<U> transformedList = new ArrayList<>();
        for (T element : list) {
            transformedList.add(trans(element));
        }
        return transformedList;
    }
