### Solution:
```javascript
class Component {
  constructor(value, child = null) {
    this.value = value;
    this.child = child;
  }

  disconnect() {
    this.child = null;
  }
}

class LinkedListWithDisconnect {
  constructor() {
    this.head = null;
    this.lastComponent = null;
  }

  add(component) {
    if (this.head === null) {
      this.head = component;
    } else {
      this.lastComponent.child = component;
    }
    this.lastComponent = component;
  }

  disconnect() {
    if (this.lastComponent !== null && this.lastComponent.child === null) {
      if (this.head === this.lastComponent) {
        this.head = null;
      } else {
        let current = this.head;
        while (current.child !== this.lastComponent) {
          current = current.child;
        }
        current.disconnect();
        this.lastComponent = current;
      }
    }
  }

  getLastComponent() {
    return this.lastComponent;
  }
}

// Example usage
