import java.util.HashMap;
import java.util.Map;

class ViewManager {
    private Map<Integer, Boolean> views;

    public ViewManager() {
        views = new HashMap<>();
    }

    public void createView(int viewId) {
        views.putIfAbsent(viewId, true);
    }

