public static bool RequiresByteReversal(Endianness current, Endianness required)
{
    bool systemIsLittleEndian = ArrayOps.SystemEndiannessIsLittleEndian();

    if (current == Endianness.System)
    {
        if (required == Endianness.Little)
        {
