#include <cmath>

FMModulator::FMModulator(double modulationIndex) : modulationIndex(modulationIndex) {}

std::vector<double> FMModulator::modulate(const std::vector<double>& inputSignal) {
    std::vector<double> modulatedSignal;
    double phase = 0.0;

