You are tasked with implementing a Tic-Tac-Toe game in C++. The game is played on a 3x3 grid, where two players take turns marking the spaces with their respective symbols (X and O) until one player wins or the game ends in a draw.

Your task is to implement the `mark_board` and `game_over` functions for the Tic-Tac-Toe game. The `mark_board` function takes an integer representing the position on the board (1-9) and marks it with the current player's symbol. The `game_over` function should return true if the game is over (either a player has won or the game is a draw) and false otherwise.

You are provided with the following code snippet as a test case for your implementation:

```
game->mark_board(1);  //X move
REQUIRE(game->game_over() == false);
game->mark_board(2);
REQUIRE(game->game_over() == false);
game->mark_board(3);
REQUIRE(game->game_over() == false);
game->mark_board(4);
REQUIRE(game->game_over() == false);
game->mark_board(5);
REQUIRE(game->game_over() == false);
game->mark_board(7);
REQUIRE(game->game_over() == false);
```

Your task is to implement the `mark_board` and `game_over` functions to pass the given test case and ensure the game logic is correctly implemented.

### Solution:
```cpp
#include <iostream>
#include <vector>

class TicTacToe {
private:
    std::vector<std::vector<char>> board;
    char current_player;

public:
    TicTacToe() : board(3, std::vector<char>(3, ' ')), current_player('X') {}

    void mark_board(int position) {
        int row = (position - 1) / 3;
        int col = (position - 1) % 3;

        if (board[row][col] == ' ') {
            board[row][col] = current_player;
            current_player = (current_player == 'X') ? 'O' : 'X';
        }
    }

    bool check_winner(char player) {
        // Check rows, columns, and diagonals for a win
        for (int i = 0; i < 3; ++i) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;  // Row win
            }
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                return true;  // Column win
            }
        }
        if ((board[0][0] == player && board[1][1] == player && board[2][2] == player) ||
            (board[0][2] == player && board[1][1] == player && board[2][0] == player)) {
            return true;  // Diagonal win
        }
        return false;
    }

    bool game_over() {
        // Check for a win
        if (check_winner('X') || check_winner('O')) {
            return true;
        }

        // Check for a draw
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                if (board[i][j] == ' ') {
                    return false;  // Game is not over, there are empty spaces
                }
            }
        }
        return true;  // Game is a draw
    }
};

int main() {
    TicTacToe* game = new TicTacToe();
    game->mark_board(1);  // X move
    std::cout << "Game over? " << (game->game_over() ? "Yes" : "No") << std::endl;
    game->mark_board(2);
    std::cout << "Game over? " << (game->game_over() ? "Yes" : "No") << std::endl;
    game->mark_board(3);
    std::cout << "Game over? " << (game->game_over() ? "Yes" : "No") << std::endl;
    game->mark_board(4);
    std::cout << "Game over? " << (game->game_over() ? "Yes" : "No") << std::endl;
    game->mark_board(5);
    std::cout << "Game over? " << (game->game_over() ? "Yes" : "No") << std::endl;
    game->mark_board(7);
    std::cout << "Game over? " << (game->game_over() ? "Yes" : "No") << std::endl;

    delete game;
    return 0;
}
```

