### Problem:
You are tasked with creating a command-line utility for copying files with specific options. The utility should accept command-line arguments for the source file, target location, and an optional flag to override the target file if it already exists.

Your task is to implement a C# program that parses command-line arguments and performs the file copy operation based on the provided options.

The command-line arguments should be in the following format:
```
copy --source <source_file_path> --target <target_directory_path> [--override]
```
Where:
- `--source` specifies the path of the source file to be copied.
- `--target` specifies the directory where the source file should be copied.
- `--override` (optional) indicates whether to override the target file if it already exists.

Your program should handle the following scenarios:
1. If the `--source` or `--target` arguments are missing, the program should display an error message indicating the missing argument and provide usage instructions.
2. If the source file does not exist, the program should display an error message and terminate.
3. If the target directory does not exist, the program should create the directory before copying the file.
4. If the `--override` flag is provided and the target file already exists, it should be overwritten. If the flag is not provided and the target file exists, the program should display a confirmation prompt before overwriting the file.

### Solution:
```csharp
using System;
using System.IO;
using CommandLine;
using CommandLine.Text;

namespace FileCopyUtility
{
    public class CopyOptions
    {
        [Option('s', "source", Required = true, HelpText = "Path of the source file to be copied")]
        public string Source { get; set; }

        [Option('t', "target", Required = true, HelpText = "Directory where the source file should be copied")]
        public string Target { get; set; }

        [Option('o', "override", Required = false, Default = false, HelpText = "Override the target file if it already exists")]
        public bool Override { get; set; }
    }

    class Program
    {
        static void Main(string[] args)
        {
            Parser.Default.ParseArguments<CopyOptions>(args)
                .WithParsed(options => CopyFile(options))
                .WithNotParsed(errors => HandleParseErrors(errors));
        }

        static void CopyFile(CopyOptions options)
        {
            if (!File.Exists(options.Source))
            {
                Console.WriteLine($"Error: Source file '{options.Source}' does not exist.");
                return;
            }

            if (!Directory.Exists(options.Target))
            {
                Directory.CreateDirectory(options.Target);
            }

            string targetFilePath = Path.Combine(options.Target, Path.GetFileName(options.Source));

            if (File.Exists(targetFilePath))
            {
                if (options.Override)
                {
                    File.Copy(options.Source, targetFilePath, true);
                    Console.WriteLine($"File '{options.Source}' copied to '{targetFilePath}' (overwritten).");
                }
                else
                {
                    Console.Write($"File '{targetFilePath}' already exists. Do you want to override it? (Y/N): ");
                    if (Console.ReadLine().Trim().ToUpper() == "Y")
                    {
                        File.Copy(options.Source, targetFilePath, true);
                        Console.WriteLine($"File '{options.Source}' copied to '{targetFilePath}' (overwritten).");
                    }
                    else
                    {
                        Console.WriteLine("File copy operation aborted.");
                    }
                }
            }
            else
            {
                File.Copy(options.Source, targetFilePath);
                Console.WriteLine($"File '{options.Source}' copied to '{targetFilePath}'.");
            }
        }

        static void HandleParseErrors(System.Collections.Generic.IEnumerable<Error> errors)
        {
            var helpText = HelpText.AutoBuild(Parser.Default.Settings, Parser.Default.ParseArguments<CopyOptions>(new string[] { "--help" }));
            Console.WriteLine(helpText);
        }
    }
