```csharp
using System;
using System.Collections.Generic;

public sealed class PackageCallbackBridge
{
    private Dictionary<string, List<Action<string>>> eventCallbacks;

    public PackageCallbackBridge()
    {
        eventCallbacks = new Dictionary<string, List<Action<string>>>();
    }

    public void RegisterCallback(string eventType, Action<string> callback)
    {
        if (!eventCallbacks.ContainsKey(eventType))
        {
            eventCallbacks[eventType] = new List<Action<string>>();
        }
        eventCallbacks[eventType].Add(callback);
    }

    public void UnregisterCallback(string eventType, Action<string> callback)
    {
        if (eventCallbacks.ContainsKey(eventType))
        {
            eventCallbacks[eventType].Remove(callback);
        }
    }

    public void TriggerCallbacks(string eventType, string packageId)
    {
        if (eventCallbacks.ContainsKey(eventType))
        {
            foreach (var callback in eventCallbacks[eventType])
            {
                callback(packageId);
            }
        }
    }
}
