### Solution:
```php
abstract class JewelryManager {
    abstract protected function setActiveMenu($menu);
}

class GemManager extends JewelryManager {
    protected $gemstones = [];
    protected $activeMenu;

    public function __construct() {
        $this->activeMenu = "gemstones_menu";
    }

    public function addGemstone($gemstone) {
        $this->gemstones[] = $gemstone;
    }

    public function removeGemstone($gemstone) {
        $key = array_search($gemstone, $this->gemstones);
        if ($key !== false) {
            unset($this->gemstones[$key]);
        }
    }

    public function displayGemstones() {
        echo "Gemstones: " . implode(", ", $this->gemstones) . "\n";
    }

    public function setActiveMenu($menu) {
        $this->activeMenu = $menu;
    }
}

