using System;
using System.Collections.Generic;
using System.Linq;

public class BankSorter
{
    public Dictionary<string, Dictionary<string, decimal>> SortBanks(Dictionary<string, Dictionary<string, decimal>> unsortedBanks)
    {
        var sortedBanks = unsortedBanks
            .OrderByDescending(bank => bank.Value.Sum(account => account.Value))
            .ThenByDescending(bank => bank.Value.Max(account => account.Value))
            .ToDictionary(x => x.Key, x => x.Value);

        return sortedBanks;
    }
}

// Usage
public class Program
{
    public static void Main()
    {
        var unsortedBanks = new Dictionary<string, Dictionary<string, decimal>> {
            { "BankA", new Dictionary<string, decimal> { { "A1", 1000 }, { "A2", 1500 }, { "A3", 500 } } },
            { "BankB", new Dictionary<string, decimal> { { "B1", 2000 }, { "B2", 3000 } } },
            { "BankC", new Dictionary<string, decimal> { { "C1", 1200 }, { "C2", 800 }, { "C3", 1000 } } }
        };

        var bankSorter = new BankSorter();
        var sortedBanks = bankSorter.SortBanks(unsortedBanks);

        foreach (var bank in sortedBanks)
        {
            Console.WriteLine(bank.Key + ": " + string.Join(", ", bank.Value.Select(account => $"{account.Key} - {account.Value}")));
        }
    }
}
```

