public:
    virtual void execute() = 0;
    virtual void undo() = 0;
    virtual void redo() = 0;
};

// Concrete command class for selecting all items
class CSelectAllCommand : public CCommand {
private:
    std::vector<Item> selectedItems;  // Data member to store selected items
    std::vector<Item> previousSelection;  // Data member to store previous selection

public:
    CSelectAllCommand(const std::vector<Item>& items) : selectedItems(items) {}

    void execute() override {
        // Select all items
        previousSelection = selectedItems;
        selectedItems = getAllItems();  // Assume getAllItems() returns all available items
