### Problem:
You are tasked with implementing a class for rotational kinematics in a vehicle navigation system. The class, `EulerAnglesYawPitchRoll`, inherits from the `RotationalKinematics` class and is responsible for converting between Euler angles and rotation matrices, as well as calculating angular velocity and Jacobian matrices.

Your task is to complete the implementation of the `EulerAnglesYawPitchRoll` class by providing the necessary functions as specified in the code snippet. You are required to implement the following member functions:
1. `parametersToRotationMatrix`: This function takes a vector of Euler angles as input and returns the corresponding rotation matrix. Additionally, it should calculate the S matrix if the pointer `S` is provided.
2. `rotationMatrixToParameters`: This function takes a rotation matrix as input and returns the corresponding Euler angles.
3. `parametersToSMatrix`: This function takes a vector of Euler angles as input and returns the corresponding S matrix.
4. `angularVelocityAndJacobian`: This function takes two vectors `p` and `pdot` as input and calculates the angular velocity along with the Jacobian matrix.

You are expected to implement these functions using the Eigen library for linear algebra operations.

### Solution:
```cpp
#include <Eigen/Dense>

class RotationalKinematics {
  // Define the base class for rotational kinematics
};

class EulerAnglesYawPitchRoll : public RotationalKinematics {
public:
  virtual ~EulerAnglesYawPitchRoll() {}

  // Convert Euler angles to rotation matrix
  virtual Eigen::Matrix3d parametersToRotationMatrix(const Eigen::Vector3d &parameters, Eigen::Matrix3d *S = NULL) const {
    double yaw = parameters(0);
    double pitch = parameters(1);
    double roll = parameters(2);

    Eigen::Matrix3d rotationMatrix;
    rotationMatrix = Eigen::AngleAxisd(yaw, Eigen::Vector3d::UnitZ()) *
                     Eigen::AngleAxisd(pitch, Eigen::Vector3d::UnitY()) *
                     Eigen::AngleAxisd(roll, Eigen::Vector3d::UnitX());

    if (S != NULL) {
      *S = parametersToSMatrix(parameters);
    }

    return rotationMatrix;
  }

  // Convert rotation matrix to Euler angles
  virtual Eigen::Vector3d rotationMatrixToParameters(const Eigen::Matrix3d &rotationMatrix) const {
    Eigen::Vector3d parameters;
    parameters(1) = asin(-rotationMatrix(2, 0));

    if (abs(rotationMatrix(2, 0)) < 0.99999) {
      parameters(0) = atan2(rotationMatrix(1, 0), rotationMatrix(0, 0));
      parameters(2) = atan2(rotationMatrix(2, 1), rotationMatrix(2, 2));
    } else {
      parameters(0) = atan2(-rotationMatrix(0, 1), rotationMatrix(1, 1));
      parameters(2) = 0;
    }

    return parameters;
  }

  // Convert Euler angles to S matrix
  virtual Eigen::Matrix3d parametersToSMatrix(const Eigen::Vector3d &parameters) const {
    double yaw = parameters(0);
    double pitch = parameters(1);
    double roll = parameters(2);

    Eigen::Matrix3d S;
    S << 0, -sin(roll), cos(roll) * sin(pitch),
         0, cos(roll), sin(roll) * sin(pitch),
         1, 0, cos(pitch);

    return S;
  }

  // Calculate angular velocity and Jacobian matrix
  virtual Eigen::Vector3d angularVelocityAndJacobian(const Eigen::Vector3d &p, const Eigen::Vector3d &pdot, Eigen::Matrix<double, 3, 6> *Jacobian) const {
    Eigen::Vector3d omega;
    omega = p.cross(pdot) / p.squaredNorm();

    if (Jacobian != NULL) {
      // Calculate the Jacobian matrix
      Jacobian->setZero();
      (*Jacobian).block<3, 3>(0, 0) = Eigen::Matrix3d::Identity();
      (*Jacobian).block<3, 3>(0, 3) = -skewSymmetric(p);
    }

    return omega;
  }

private:
  // Helper function to calculate the skew-symmetric matrix
  Eigen::Matrix3d skewSymmetric(const Eigen::Vector3d &v) const {
    Eigen::Matrix3d S;
    S << 0, -v(2), v(1),
         v(2), 0, -v(0),
         -v(1), v(0), 0;
    return S;
  }
};
```

