#include <iostream>
#include <unordered_map>
#include <string>

class TTrGix {
private:
    std::unordered_map<std::string, int> WordH;

public:
    int AddOrGetWord(const std::string& WordStr, bool AddIfNotExistP) {
        if (AddIfNotExistP) {
            if (WordH.find(WordStr) == WordH.end()) {
                WordH[WordStr] = WordH.size();  // Assign a new ID to the word
            }
            return WordH[WordStr];
        } else {
            if (WordH.find(WordStr) != WordH.end()) {
                return WordH[WordStr];
            } else {
