### Problem:
You are tasked with implementing a simple hash table data structure in C++. The hash table should support key-value pairs, and it should handle collisions using separate chaining. You need to implement the `HashTable` class with the following functionalities:
1. `insert(key, value)`: Insert a key-value pair into the hash table. If the key already exists, update the corresponding value.
2. `remove(key)`: Remove the key-value pair associated with the given key from the hash table.
3. `get(key)`: Retrieve the value associated with the given key from the hash table. If the key does not exist, return a default value.
4. `contains(key)`: Check if the hash table contains the given key.

You should use separate chaining to handle collisions. The hash table should have a fixed size and use a simple hash function (e.g., modulo operation) to map keys to indices.

Your task is to implement the `HashTable` class and ensure that it handles collisions correctly using separate chaining.

### Solution:
```cpp
#include <iostream>
#include <vector>
#include <list>

class HashTable {
private:
    std::vector<std::list<std::pair<int, int>>> table;
    int size;

    int hash(int key) {
        return key % size;
    }

public:
    HashTable(int tableSize) : size(tableSize), table(tableSize) {}

    void insert(int key, int value) {
        int index = hash(key);
        for (auto &pair : table[index]) {
            if (pair.first == key) {
                pair.second = value;
                return;
            }
        }
        table[index].push_back(std::make_pair(key, value));
    }

    void remove(int key) {
        int index = hash(key);
        table[index].remove_if([key](const std::pair<int, int> &pair) {
            return pair.first == key;
        });
    }

    int get(int key) {
        int index = hash(key);
        for (const auto &pair : table[index]) {
            if (pair.first == key) {
                return pair.second;
            }
        }
        return -1; // Return a default value if key not found
    }

    bool contains(int key) {
        int index = hash(key);
        for (const auto &pair : table[index]) {
            if (pair.first == key) {
                return true;
            }
        }
        return false;
    }
};

int main() {
    HashTable ht(10);
    ht.insert(5, 10);
    ht.insert(15, 20);
    std::cout << ht.get(5) << std::endl;  // Output: 10
    std::cout << ht.get(15) << std::endl; // Output: 20
    std::cout << ht.contains(10) << std::endl; // Output: 0 (false)
    ht.remove(5);
    std::cout << ht.get(5) << std::endl;  // Output: -1 (default value)
    return 0;
}
```

