2. Retrieve the value associated with a given key.
3. Remove a key-value pair.

Your task is to implement the `CustomHashMap` class with the following specifications:
- The hash map should use separate chaining for collision resolution.
- The hash map should use a custom hash function to hash the keys.
- The hash map should support the following operations:
  - `void insert(int key, int value)`: Insert the key-value pair into the hash map. If the key already exists, update the corresponding value.
  - `int get(int key)`: Retrieve the value associated with the given key. If the key does not exist, return -1.
  - `void remove(int key)`: Remove the key-value pair associated with the given key if it exists.

You need to implement the `CustomHashMap` class and ensure that it passes the provided test cases.

```cpp
#include <iostream>
#include <vector>
#include <list>
#include <functional>

class CustomHashMap {
private:
    static const int SIZE = 1000;
    std::vector<std::list<std::pair<int, int>>> data;

    int customHash(int key) {
        return std::hash<int>{}(key) % SIZE;
    }

public:
    CustomHashMap() : data(SIZE) {}

    void insert(int key, int value) {
        int index = customHash(key);
        for (auto& pair : data[index]) {
            if (pair.first == key) {
                pair.second = value;
                return;
            }
        }
        data[index].emplace_back(key, value);
    }

    int get(int key) {
        int index = customHash(key);
        for (const auto& pair : data[index]) {
            if (pair.first == key) {
                return pair.second;
            }
        }
        return -1;
    }

    void remove(int key) {
        int index = customHash(key);
        data[index].remove_if([key](const std::pair<int, int>& pair) {
            return pair.first == key;
        });
    }
};

int main() {
    CustomHashMap hashMap;
    hashMap.insert(1, 1);
    hashMap.insert(2, 2);
    std::cout << hashMap.get(1) << std::endl;    // Output: 1
    std::cout << hashMap.get(3) << std::endl;    // Output: -1
    hashMap.insert(2, 1);
    std::cout << hashMap.get(2) << std::endl;    // Output: 1
    hashMap.remove(2);
    std::cout << hashMap.get(2) << std::endl;    // Output: -1
    return 0;
}
```

