### Solution:
```csharp
public void CreateDirectory(string path)
{
    string[] directories = path.Split('/');
    Directory currentDir = Root;

    for (int i = 1; i < directories.Length; i++)
    {
        string dirName = directories[i];
        Directory existingDir = currentDir.Directories.FirstOrDefault(d => d.Name == dirName);
        if (existingDir == null)
        {
            Directory newDir = new Directory(dirName);
            currentDir.AddDirectory(newDir);
            currentDir = newDir;
        }
        else
        {
            currentDir = existingDir;
        }
    }
}

public void CreateFile(string path, string fileName)
{
    string[] directories = path.Split('/');
    Directory currentDir = Root;

    for (int i = 1; i < directories.Length - 1; i++)
    {
        string dirName = directories[i];
        Directory existingDir = currentDir.Directories.FirstOrDefault(d => d.Name == dirName);
        if (existingDir == null)
        {
            // Directory does not exist, cannot create file
            return;
        }
        else
        {
            currentDir = existingDir;
        }
    }

    currentDir.AddFile(fileName);
}

public List<string> ListFiles(string path)
{
    string[] directories = path.Split('/');
    Directory currentDir = Root;

    for (int i = 1; i < directories.Length; i++)
    {
        string dirName = directories[i];
        Directory existingDir = currentDir.Directories.FirstOrDefault(d => d.Name == dirName);
        if (existingDir == null)
        {
            // Directory does not exist, return empty list
            return new List<string>();
        }
        else
        {
            currentDir = existingDir;
        }
    }

    return currentDir.Files;
}

public List<string> SearchFiles(string path, string keyword)
{
    List<string> result = new List<string>();
    string[] directories = path.Split('/');
    Directory currentDir = Root;

    for (int i = 1; i < directories.Length; i++)
    {
        string dirName = directories[i];
        Directory existingDir = currentDir.Directories.FirstOrDefault(d => d.Name == dirName);
        if (existingDir == null)
        {
            // Directory does not exist, return empty list
            return new List<string>();
        }
        else
        {
            currentDir = existingDir;
        }
    }

    foreach (string file in currentDir.Files)
    {
        if (file.Contains(keyword))
        {
            result.Add(file);
        }
    }

    return result;
}
```

This solution provides the implementation for creating directories, creating files, listing files in a directory, and searching for files containing a specific keyword within a given directory path. The `Directory` class represents a directory in the file system, and the `FileSystem` class provides the necessary functions to manipulate the file system.

