You are tasked with implementing a hash table data structure in C++. The hash table should support the following operations:
1. Insertion of a key-value pair.
2. Retrieval of the value associated with a given key.
3. Deletion of a key-value pair.

Your implementation should handle potential naming conflicts with the `hash` variable in the `std` namespace, which could lead to compilation errors or runtime issues. Additionally, you should avoid using the variable name `y1` as a global variable due to potential conflicts with the `math.h` library.

Design and implement a hash table class that addresses these naming conflicts and provides the required functionality. Your implementation should include appropriate error handling and should be efficient in terms of time complexity for the supported operations.

### Solution:
```cpp
#include <iostream>
#include <list>
#include <utility>

class HashTable {
private:
    static const int tableSize = 10;
    std::list<std::pair<int, int>> table[tableSize];

    int hashFunction(int key) {
        return key % tableSize;
    }

public:
    void insert(int key, int value) {
        int index = hashFunction(key);
        for (auto& pair : table[index]) {
            if (pair.first == key) {
                std::cerr << "Key already exists. Use update instead of insert." << std::endl;
                return;
            }
        }
        table[index].emplace_back(key, value);
    }

    int retrieve(int key) {
        int index = hashFunction(key);
        for (auto& pair : table[index]) {
            if (pair.first == key) {
                return pair.second;
            }
        }
        std::cerr << "Key not found." << std::endl;
        return -1;  // Assuming -1 represents key not found
    }

    void remove(int key) {
        int index = hashFunction(key);
        for (auto it = table[index].begin(); it != table[index].end(); ++it) {
            if (it->first == key) {
                table[index].erase(it);
                return;
            }
        }
        std::cerr << "Key not found. No deletion performed." << std::endl;
    }
};

int main() {
    HashTable ht;
    ht.insert(5, 10);
    ht.insert(15, 20);
    std::cout << ht.retrieve(5) << std::endl;  // Output: 10
    std::cout << ht.retrieve(15) << std::endl;  // Output: 20
    ht.remove(5);
    std::cout << ht.retrieve(5) << std::endl;  // Output: Key not found.
    return 0;
}
```

