```python
class MetaClass(type):
    def __new__(mcs, name, bases, clsdict):
        return super().__new__(mcs, name, bases, clsdict)

    def __init__(cls, name, bases, clsdict):
        super().__init__(name, bases, clsdict)

    def __call__(cls, *args, **kwargs):
        return super().__call__(*args, **kwargs)

    def __setattr__(cls, key, value):
        if key == 'meta_option':
            msg = f'{cls.__name__} Meta option must be True or False'
            assert isinstance(value, bool), msg
        super().__setattr__(key, value)

    def contribute_to_class(cls, mcs_args, value):
        if not value:
            return

        table_args = mcs_args.clsdict.get('__table_args__', {})
        table_args['extend_existing'] = True
        mcs_args.clsdict['__table_args__'] = table_args
```

