    const double A = 0.01;  // m^2 (assuming a small cross-sectional area for simplicity)

    double vx = initialVelocity * cos(launchAngle);
    double vy = initialVelocity * sin(launchAngle);

    double x = vx * time;
    double y = vy * time - 0.5 * g * time * time;

    double ay = -g - 0.5 * (Cd * rho * A / mass) * vy * vy;

    std::cout << "At time " << time << "s, the projectile is at position (" << x << "m, " << y << "m)" << std::endl;
    std::cout << "Vertical acceleration at time " << time << "s is " << ay << "m/s^2" << std::endl;
}
```

