import java.util.ArrayList;
import java.util.List;

public class Server {
    private List<AbstractNioWorker> workers;

    public void start() {
        workers = new ArrayList<>();
        // Initialize and start each worker thread
        for (int i = 0; i < numWorkerThreads; i++) {
            AbstractNioWorker worker = new AbstractNioWorker(); // Initialize worker thread
