public class KeyboardLayoutFormatter {
    public String formatKeyboardLayout(List<String> secondKeyboardRow, List<String> thirdKeyboardRow, List<String> fourthKeyboardRow, String checkServerIp) {
        StringBuilder formattedOutput = new StringBuilder();

        formattedOutput.append("Keyboard Layout:\n");
        formattedOutput.append("1st Row: \n");
        formattedOutput.append("2nd Row: ");
        for (String key : secondKeyboardRow) {
