You are tasked with creating a program that simulates a memory allocation and deallocation process. The program should implement a custom memory management system using a linked list data structure to keep track of allocated and deallocated memory blocks.

Your task is to implement a C++ program that manages memory allocation and deallocation using a linked list. The program should provide functions for allocating memory, deallocating memory, and printing the current state of the memory blocks.

Your program should have the following functionalities:
1. Allocate memory: Implement a function to allocate a block of memory of a specified size. The function should return a pointer to the allocated memory block.
2. Deallocate memory: Implement a function to deallocate a previously allocated memory block. The function should take a pointer to the memory block as an argument and free the memory.
3. Print memory state: Implement a function to print the current state of the memory blocks, including the addresses and sizes of allocated and deallocated memory blocks.

You should use a linked list to manage the memory blocks, with each node in the list representing a memory block. The program should handle memory fragmentation and reuse deallocated memory blocks when possible.

Your program should be able to handle multiple memory allocation and deallocation requests and maintain the integrity of the memory blocks.

### Solution:
```cpp
#include <iostream>
#include <cstdlib>

struct MemoryBlock {
    void* address;
    size_t size;
    bool allocated;
    MemoryBlock* next;
};

class MemoryManager {
private:
    MemoryBlock* head;

public:
    MemoryManager() : head(nullptr) {}

    void* allocate(size_t size) {
        MemoryBlock* current = head;
        MemoryBlock* prev = nullptr;

        while (current != nullptr) {
            if (!current->allocated && current->size >= size) {
                current->allocated = true;
                return current->address;
            }
            prev = current;
            current = current->next;
        }

        // Allocate new memory block
        void* newBlock = std::malloc(size);
        MemoryBlock* newMemoryBlock = new MemoryBlock{newBlock, size, true, nullptr};

        if (prev == nullptr) {
            head = newMemoryBlock;
        } else {
            prev->next = newMemoryBlock;
        }

        return newBlock;
    }

    void deallocate(void* address) {
        MemoryBlock* current = head;

        while (current != nullptr) {
            if (current->address == address) {
                current->allocated = false;
                break;
            }
            current = current->next;
        }
    }

    void printMemoryState() {
        MemoryBlock* current = head;

        std::cout << "Memory State:" << std::endl;
        while (current != nullptr) {
            std::cout << "Address: " << current->address << ", Size: " << current->size << ", Allocated: " << (current->allocated ? "Yes" : "No") << std::endl;
            current = current->next;
        }
    }
};

int main() {
    MemoryManager memoryManager;

    // Allocate memory blocks
    void* block1 = memoryManager.allocate(100);
    void* block2 = memoryManager.allocate(200);
    void* block3 = memoryManager.allocate(150);

    memoryManager.printMemoryState();

    // Deallocate memory block 2
    memoryManager.deallocate(block2);

    memoryManager.printMemoryState();

    // Allocate a new memory block
    void* block4 = memoryManager.allocate(300);

    memoryManager.printMemoryState();

    return 0;
}
```

