import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class ArchitectureFilter {
    public static List<String> filterArchitectures(List<String> architectures) {
        List<String> validArchitectures = Arrays.asList("x86", "x86_64", "arm", "arm64", "mips");
