### Solution:
```cpp
#include <vector>
#include <stack>
#include <limits>

namespace elang {
    namespace {
        typedef std::vector<int> IntVector;

        class MinStack {
        private:
            std::stack<int> dataStack;
            std::stack<int> minStack;

        public:
            void push_back(int val) {
                dataStack.push(val);
                if (minStack.empty() || val <= minStack.top()) {
                    minStack.push(val);
                }
            }

            void pop_back() {
                if (dataStack.top() == minStack.top()) {
                    minStack.pop();
                }
                dataStack.pop();
            }

            int get_min() {
                return minStack.top();
            }
        };
    }
}
