#include <iostream>
#include <fstream>
#include <vector>

class CustomArray {
private:
    std::vector<int32_t> elements;

public:
    // Overload the square brackets operator to access elements by index
    int32_t operator[](size_t k) {
        return elements[k];
    }

    // Write the elements of the array to the output stream in binary format
    void writeToStream(std::ostream& os) {
        for (size_t k = 0; k < elements.size(); ++k) {
            int32_t act = this->operator[](k);
            os.write(reinterpret_cast<const char*>(&act), sizeof(int32_t));
        }
    }

    // Add elements to the array
    void addElement(int32_t element) {
        elements.push_back(element);
    }
};

