                while (std::isdigit(*s2)) {
                    num2 = num2 * 10 + (*s2 - '0');
                    s2++;
                }
                if (num1 != num2) {
                    return (num1 < num2) ? -1 : 1;
                }
            } else {
                if (*s1 != *s2) {
                    return (*s1 < *s2) ? -1 : 1;
                }
                s1++;
                s2++;
            }
        }

        if (*s1) {
            return 1; // str1 is longer
        } else if (*s2) {
            return -1; // str2 is longer
        } else {
            return 0; // strings are equal
        }
    }

    static void skipSpaces(const char *&s) {
        while (isSpace(*s)) s++;
    }
};
```

