### Problem:
You are tasked with implementing a simple text editor for a digital notebook. The notebook consists of multiple pages, each containing a grid of rows and columns. The text editor provides the following operations:

1. `write(int const & page, int const & row, int const & col, Direction dir, string const & str)`: Writes the given string `str` starting from the specified page, row, and column in the specified direction (`dir`). The direction can be either "right" or "down".

2. `erase(int page, int row, int col, Direction dir, int length)`: Erases the specified number of characters (`length`) starting from the given page, row, and column in the specified direction (`dir`).

3. `read(int page, int row, int col, Direction dir, int length)`: Reads and returns the string of the specified length starting from the given page, row, and column in the specified direction (`dir`).

4. `show(int page)`: Displays the content of the specified page.

You need to implement the text editor operations to manipulate the content of the digital notebook.

You are given the following enum for the `Direction`:

```cpp
enum Direction {
    RIGHT,
    DOWN
};
```

You should implement the functions `write`, `erase`, `read`, and `show` to perform the specified operations on the digital notebook.

### Solution:
```cpp
#include <iostream>
#include <vector>

enum Direction {
    RIGHT,
    DOWN
};

class DigitalNotebook {
private:
    std::vector<std::vector<std::string>> pages;

public:
    DigitalNotebook(int numPages, int rows, int cols) {
        pages.resize(numPages, std::vector<std::string>(rows, std::string(cols, ' ')));
    }

    void write(int const &page, int const &row, int const &col, Direction dir, std::string const &str) {
        int len = str.length();
        int r = row, c = col;
        for (char ch : str) {
            if (r < 0 || r >= pages[page].size() || c < 0 || c >= pages[page][0].size()) {
                std::cerr << "Error: Out of bounds write operation\n";
                return;
            }
            pages[page][r][c] = ch;
            if (dir == RIGHT) {
                c = (c + 1) % pages[page][0].size();
                if (c == 0) {
                    r = (r + 1) % pages[page].size();
                }
            } else if (dir == DOWN) {
                r = (r + 1) % pages[page].size();
            }
        }
    }

    void erase(int page, int row, int col, Direction dir, int length) {
        int r = row, c = col;
        for (int i = 0; i < length; ++i) {
            if (r < 0 || r >= pages[page].size() || c < 0 || c >= pages[page][0].size()) {
                std::cerr << "Error: Out of bounds erase operation\n";
                return;
            }
            pages[page][r][c] = ' ';
            if (dir == RIGHT) {
                c = (c + 1) % pages[page][0].size();
                if (c == 0) {
                    r = (r + 1) % pages[page].size();
                }
            } else if (dir == DOWN) {
                r = (r + 1) % pages[page].size();
            }
        }
    }

    std::string read(int page, int row, int col, Direction dir, int length) {
        std::string result;
        int r = row, c = col;
        for (int i = 0; i < length; ++i) {
            if (r < 0 || r >= pages[page].size() || c < 0 || c >= pages[page][0].size()) {
                std::cerr << "Error: Out of bounds read operation\n";
                return "";
            }
            result += pages[page][r][c];
            if (dir == RIGHT) {
                c = (c + 1) % pages[page][0].size();
                if (c == 0) {
                    r = (r + 1) % pages[page].size();
                }
            } else if (dir == DOWN) {
                r = (r + 1) % pages[page].size();
            }
        }
        return result;
    }

    void show(int page) {
        for (const auto &row : pages[page]) {
            std::cout << row << std::endl;
        }
    }
};

int main() {
    DigitalNotebook notebook(3, 4, 5);
    notebook.write(0, 0, 0, RIGHT, "Hello");
    notebook.write(0, 1, 0, DOWN, "World");
    notebook.show(0);
    std::cout << "Read: " << notebook.read(0, 0, 0, RIGHT, 5) << std::endl;
    notebook.erase(0, 0, 0, RIGHT, 5);
    notebook.show(0);
    return 0;
}
```

