```cpp
#include <iostream>
#include <iomanip>
#include <sstream>

class util {
public:
    static const int LARGE_COL_WIDTH = 20;
    static const int SMALL_COL_WIDTH = 10;
    static const std::string SPACE;

    static std::string column(std::string str, bool large) {
        unsigned long colSize = large ? LARGE_COL_WIDTH : SMALL_COL_WIDTH;
        if (str.size() > colSize) str = str.substr(0, colSize - 4) + "... ";
        std::ostringstream ss;
        ss << std::setw((int)colSize) << std::left << str << SPACE;
        return ss.str();
    }

    static std::string to_string(float n) {
