### Solution:
```cpp
#include <iostream>
using namespace std;

class Stack {
private:
    int top;
    int capacity;
    int* elements;

public:
    Stack() {
        top = -1;
        capacity = 100;
        elements = new int[capacity];
    }

    ~Stack() {
        delete[] elements;
    }

    void push(int value) {
        if (top < capacity - 1) {
            top++;
            elements[top] = value;
        } else {
            cout << "Stack overflow! Cannot push more elements." << endl;
        }
    }

    int pop() {
        if (top >= 0) {
            int popped = elements[top];
            top--;
            return popped;
        } else {
            cout << "Stack underflow! Cannot pop from an empty stack." << endl;
            return -1; // Assuming -1 as an error indicator for an empty stack
        }
    }

    int peek() {
        if (top >= 0) {
            return elements[top];
        } else {
            cout << "Stack is empty. No top element to peek." << endl;
            return -1; // Assuming -1 as an error indicator for an empty stack
        }
    }

    void display() {
        if (top >= 0) {
            cout << "Stack elements: ";
            for (int i = top; i >= 0; i--) {
                cout << elements[i] << " ";
            }
            cout << endl;
        } else {
            cout << "Stack is empty. No elements to display." << endl;
        }
    }
};

int main() {
    Stack stack;
    stack.push(5);
    stack.push(10);
    stack.push(15);
    stack.display();
    cout << "\nTop element is " << stack.peek() << endl;
    return 0;
}
```

