#include <iostream>

class Delegate {
public:
    virtual void AltegoCaptureFPSUpdated(AltegoCapture* capture, float fps) = 0;
};

class AltegoCapture {
private:
    Delegate* _delegate;
    int count;
    double t;

public:
    AltegoCapture(Delegate* delegate) : _delegate(delegate), count(0), t(0) {}

    void processFrame() {
        // Capture and process the frame

        // Calculate FPS
        count++;
        if (count == 100) {
            t = cv::getTickCount();
            count = 0;
            if (_delegate != nullptr) {
                float fps = 100.f / ((cv::getTickCount() - t) / cv::getTickFrequency());
                _delegate->AltegoCaptureFPSUpdated(this, fps);
            }
        }
    }
};
