    public void Run()
    {
        for (bool quit = false; !quit; )
        {
            Console.WriteLine("Enter command: (a)dd, (r)emove, (l)ist, (q)uit");
            char command = Console.ReadKey(true).KeyChar;

            switch (command)
            {
                case 'a':
                    AddDevice();
                    break;

                case 'r':
                    RemoveDevice();
                    break;

                case 'l':
                    ListDevices();
                    break;

                case 'q':
                    quit = true;
                    break;

                default:
                    Console.WriteLine("Invalid command. Please try again.");
                    break;
            }
        }
    }

    private void AddDevice()
    {
        Console.Write("Enter device name: ");
        string deviceName = Console.ReadLine();
        devices.Add(nextDeviceId, deviceName);
        Console.WriteLine($"Device '{deviceName}' added with ID: {nextDeviceId}");
        nextDeviceId++;
    }

    private void RemoveDevice()
    {
        Console.Write("Enter device ID to remove: ");
        if (int.TryParse(Console.ReadLine(), out int deviceId))
        {
            if (devices.ContainsKey(deviceId))
            {
                string deviceName = devices[deviceId];
                devices.Remove(deviceId);
                Console.WriteLine($"Device '{deviceName}' with ID {deviceId} removed.");
            }
            else
            {
                Console.WriteLine("Device ID not found.");
            }
        }
        else
        {
            Console.WriteLine("Invalid device ID.");
        }
    }

    private void ListDevices()
    {
        if (devices.Count == 0)
        {
            Console.WriteLine("No devices found.");
        }
        else
        {
            Console.WriteLine("List of devices:");
            foreach (var device in devices)
            {
                Console.WriteLine($"ID: {device.Key}, Name: {device.Value}");
            }
        }
    }
}

class Program
{
    static void Main()
    {
        DeviceManager manager = new DeviceManager();
        manager.Run();
    }
}
```

This solution provides a complete program that manages a list of devices in a smart home system. It allows users to add, remove, and list devices, as well as the option to quit the program. The program continuously prompts the user for input and performs the corresponding operations based on the user's commands.

### Problem:
You are tasked with implementing a custom data structure in Java that simulates a simplified version of a stack. The stack should support the following operations:
1. `push(int val)`: Add an integer `val` to the top of the stack.
2. `pop()`: Remove the element at the top of the stack and return its value.
3. `peek()`: Return the value of the element at the top of the stack without removing it.
4. `isEmpty()`: Return a boolean indicating whether the stack is empty.

Your task is to implement the `CustomStack` class that provides the above operations. Additionally, the `CustomStack` should have a constructor that takes an integer `capacity` as a parameter, which specifies the maximum capacity of the stack. If the number of elements in the stack exceeds the capacity, further `push` operations should be ignored.

You should implement the `CustomStack` using an array as the underlying data structure.

Your implementation should adhere to the following constraints:
- 1 <= capacity <= 1000
- -1000 <= val <= 1000
- The total number of operations will not exceed 10000
- All `pop` and `peek` operations are valid (i.e., when the stack is not empty)

Example:
```java
CustomStack customStack = new CustomStack(3); // Stack is Empty []
customStack.push(1);                          // Stack becomes [1]
customStack.push(2);                          // Stack becomes [1, 2]
customStack.pop();                            // Return 2, Stack becomes [1]
customStack.push(2);                          // Stack becomes [1, 2]
customStack.push(3);                          // Stack becomes [1, 2, 3]
customStack.push(4);                          // Stack becomes [1, 2, 3] (Capacity reached)
customStack.increment(5, 100);                // Stack becomes [101, 102, 103]
customStack.increment(2, 100);                // Stack becomes [201, 202, 103]
customStack.pop();                            // Return 103, Stack becomes [201, 202]
customStack.pop();                            // Return 202, Stack becomes [201]
customStack.pop();                            // Return 201, Stack becomes []
customStack.pop();                            // Return -1 (Stack is Empty)
```

### Solution:
```java
class CustomStack {
    private int[] stack;
    private int capacity;
    private int size;

    public CustomStack(int capacity) {
        this.capacity = capacity;
        this.stack = new int[capacity];
        this.size = 0;
    }

    public void push(int val) {
        if (size < capacity) {
            stack[size++] = val;
        }
    }

    public int pop() {
        if (size > 0) {
            return stack[--size];
        }
        return -1;
    }

    public int peek() {
        if (size > 0) {
            return stack[size - 1];
        }
        return -1;
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public void increment(int k, int val) {
        int end = Math.min(k, size);
        for (int i = 0; i < end; i++) {
            stack[i] += val;
        }
    }
}
```

